// Custom logger that redacts known sensitive patterns
const createSecureLogger = () => {
  const sensitivePatterns = [
    /password['"]?\s*[:=]\s*['"]?([^\s'"']+)/gi,
    /secret['"]?\s*[:=]\s*['"]?([^\s'"']+)/gi,
    /key['"]?\s*[:=]\s*['"]?([^\s'"']+)/gi,
    /token['"]?\s*[:=]\s*['"]?([^\s'"']+)/gi
  ];

  return {
    log: (level, message, meta = {}) => {
      // Redact sensitive information from message
      let sanitizedMessage = message;
      sensitivePatterns.forEach(pattern => {
        sanitizedMessage = sanitizedMessage.replace(pattern, '$1=[REDACTED]');
      });

      // Redact sensitive information in meta
      const sanitizeObject = (obj) => {
        if (typeof obj !== 'object' || obj === null) return obj;

        return Object.keys(obj).reduce((acc, key) => {
          const lowerKey = key.toLowerCase();
          if (sensitivePatterns.some(p => p.test(lowerKey))) {
            acc[key] = '[REDACTED]';
          } else if (typeof obj[key] === 'object' && obj[key] !== null) {
            acc[key] = sanitizeObject(obj[key]);
          } else {
            acc[key] = obj[key];
          }
          return acc;
        }, {});
      };

      const sanitizedMeta = sanitizeObject(meta);
      console[level]({ message: sanitizedMessage, meta: sanitizedMeta });
    }
  };
};

// Usage
const logger = createSecureLogger();
logger.log('info', 'User logged in', { userId: 123, password: 'secret123' });
// Output: { message: "User logged in", meta: { userId: 123, password: "[REDACTED]" } }
```

