const crypto = require('crypto');

// Create a verification token that proves knowledge of secret without revealing it
function createSecretVerification(secret) {
  // Use a application-specific salt and purpose
  const salt = 'app-verification-salt-v1';
  const purpose = 'credential-rotation-verification';

