const crypto = require('crypto');

class SecureAuditLogger {
  constructor(appName) {
    this.appName = appName;
    this.rotationSalt = process.env.AUDIT_LOG_SALT || 'default-app-salt-change-in-production';
  }

  // Log rotation event without exposing secrets
  logRotationEvent(variableName, oldVersionId, newVersionId, status, details = {}) {
    const timestamp = new Date().toISOString();
    const logEntry = {
      timestamp,
      app: this.appName,
      event: 'credential_rotation',
      variable: variableName,
      oldVersion: oldVersionId,
      newVersion: newVersionId,
      status: status, // SUCCESS, FAILED, PARTIAL
      details: {
        ...details,
        // Add verification hash if needed (never the actual secret)
        verificationHash: this.createVerificationHash(variableName, newVersionId)
      }
    };

    console.info('AUDIT:', JSON.stringify(logEntry));
  }

  // Create verification hash for later validation
  createVerificationHash(variableName, versionId) {
    const hmac = crypto.createHmac('sha256', this.rotationSalt);
    hmac.update(this.appName);
    hmac.update(variableName);
    hmac.update(versionId);
    return hmac.digest('hex');
  }

  // Verify a rotation entry (for audit checking)
  verifyRotationEntry(logEntry) {
    const expectedHash = this.createVerificationHash(
      logEntry.variable, 
      logEntry.details.newVersion
    );
    return expectedHash === logEntry.details.verificationHash;
  }
}

