  // In a real app, you would fetch users from database with proper authorization
  // This example shows conceptually how to limit data exposure
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  // Only expose necessary fields based on user role/permissions
