    /(\%22)|(").*(\%22)|(")/i, // Quote patterns
    /(\%3B)|(;).*(\%3B)|(;)/i, // Command injection patterns
    /(\%2C)|(,).*(\%2C)|(,)/i  // CSV injection patterns
  ];

  const checkForSuspiciousInput = (input) => {
